<?php
namespace App\Http\Controllers\Api\V1;
use App\Http\Controllers\Controller; use App\Http\Responses\ApiResponse; use App\Models\ExternalElective; use Illuminate\Http\JsonResponse;
class ExternalElectiveController extends Controller { public function index(\Illuminate\Http\Request $request): JsonResponse { return ApiResponse::success(ExternalElective::with(['student:id,university_number,full_name_ar,full_name_en','course:id,code,name_ar,name_en'])->when(!$request->boolean('show_archived'), fn($q)=>$q->whereNull('archived_at'))->orderByDesc('start_date')->get()); } public function store(\Illuminate\Http\Request $r):JsonResponse{$d=$r->validate(['student_id'=>['required','exists:students,id'],'course_id'=>['nullable','exists:courses,id'],'academic_year'=>['nullable','string'],'organization'=>['nullable','string'],'country'=>['nullable','string'],'specialty'=>['nullable','string'],'start_date'=>['nullable','date'],'end_date'=>['nullable','date'],'external_supervisor'=>['nullable','string'],'approval_status'=>['nullable','string'],'external_evaluation'=>['nullable','string'],'score'=>['nullable','numeric']]);return ApiResponse::success(ExternalElective::create($d),'External elective created.',[],201);} public function update(\Illuminate\Http\Request $r,ExternalElective $externalElective):JsonResponse{$externalElective->update($r->validate(['approval_status'=>['nullable','string'],'external_evaluation'=>['nullable','string'],'score'=>['nullable','numeric'],'recognition_status'=>['nullable','string'],'notes'=>['nullable','string']]));return ApiResponse::success($externalElective->fresh());} public function archive(ExternalElective $externalElective):JsonResponse{$externalElective->update(['archived_at'=>now()]);return ApiResponse::success($externalElective->fresh(),'External elective archived.');} }
